diff --git a/src/Invoke-Mirror.ps1 b/src/Invoke-Mirror.ps1
index 1111111..7777777 100644
--- a/src/Invoke-Mirror.ps1
+++ b/src/Invoke-Mirror.ps1
@@ -1,7 +1,14 @@
+function Invoke-RobocopyExit {
+    param($Source, $Destination)
+    & robocopy.exe $Source $Destination /MIR
+    return $LASTEXITCODE
+}
+
 function Invoke-Mirror {
     param($Source, $Destination)
-    & robocopy.exe $Source $Destination /MIR
-    if ($LASTEXITCODE -le 7) { return $true }
+    $copyExit = Invoke-RobocopyExit -Source $Source -Destination $Destination
+    Write-Verbose ("robocopy exit={0}" -f $copyExit)
+    if ($copyExit -le 7) { return $true }
     return $false
 }

diff --git a/tests/Invoke-Mirror.Tests.ps1 b/tests/Invoke-Mirror.Tests.ps1
index 3333333..8888888 100644
--- a/tests/Invoke-Mirror.Tests.ps1
+++ b/tests/Invoke-Mirror.Tests.ps1
@@ -1,3 +1,31 @@
 Describe 'Invoke-Mirror exit classification' {
+    BeforeAll {
+        . "$PSScriptRoot/../src/Invoke-Mirror.ps1"
+    }
+
+    It 'returns success for robocopy exit 0' {
+        Mock Invoke-RobocopyExit { 0 }
+        Invoke-Mirror -Source source -Destination destination | Should -BeTrue
+        Assert-MockCalled Invoke-RobocopyExit -Times 1
+    }
+
+    It 'returns success for robocopy exit 7' {
+        Mock Invoke-RobocopyExit { 7 }
+        Invoke-Mirror -Source source -Destination destination | Should -BeTrue
+        Assert-MockCalled Invoke-RobocopyExit -Times 1
+    }
+
+    It 'returns failure for robocopy exit 8' {
+        Mock Invoke-RobocopyExit { 8 }
+        Invoke-Mirror -Source source -Destination destination | Should -BeFalse
+        Assert-MockCalled Invoke-RobocopyExit -Times 1
+    }
+
+    It 'captures LASTEXITCODE immediately in the native helper' {
+        $source = Get-Content -Raw "$PSScriptRoot/../src/Invoke-Mirror.ps1"
+        $helper = $source.Substring($source.IndexOf('function Invoke-RobocopyExit'), $source.IndexOf('function Invoke-Mirror') - $source.IndexOf('function Invoke-RobocopyExit'))
+        $nativeIndex = $helper.IndexOf('& robocopy.exe')
+        $captureIndex = $helper.IndexOf('return $LASTEXITCODE')
+        $nativeIndex | Should -BeGreaterThan -1
+        $captureIndex | Should -BeGreaterThan $nativeIndex
+        $helper.Substring($nativeIndex, $captureIndex - $nativeIndex) | Should -Not -Match 'Write-Verbose|where\.exe'
+    }
 }
